package compiler.runtime;

import compiler.parser.Ast;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * 结构检查：验证 {@code introduces} 声明的算子是否都被 {@code asserts} 定义。
 *
 * <p>这是「introduces 与 asserts 是否相符」的静态部分：不看取值，只看声明与定义是否对应。
 * 一个算子可以通过下列任一方式获得定义：</p>
 * <ul>
 *   <li>出现在某条等式左侧的根位置（{@code lookup(...) == ...}、{@code (e ∈ c) == ...}）</li>
 *   <li>出现在 {@code generated by} / {@code partitioned by} 子句中</li>
 *   <li>出现在 {@code converts} 子句中</li>
 * </ul>
 */
public final class StructureCheck {

    private StructureCheck() {
    }

    /** 一条结构检查发现。 */
    public record Finding(String message) {
        @Override
        public String toString() {
            return message;
        }
    }

    public static List<Finding> check(Ast.Trait trait) {
        List<Finding> findings = new ArrayList<>();
        if (trait == null) {
            return findings;
        }

        Ast.Introduces intro = section(trait, Ast.Introduces.class);
        if (intro == null || intro.signatures().isEmpty()) {
            return findings;
        }

        Set<String> defined = definedNames(trait);
        Set<String> parameters = new LinkedHashSet<>(trait.parameters());

        for (Ast.Signature signature : intro.signatures()) {
            String operator = operatorOf(signature.name());
            if (operator == null) {
                continue;                       // 字面量签名，如 0,1
            }
            if (parameters.contains(operator)) {
                continue;                       // 算子形参，由实例化方提供定义
            }
            if (!defined.contains(operator)) {
                findings.add(new Finding("算子 " + signature.name()
                        + " 在 introduces 中声明，但 asserts 中没有定义它的等式"));
            }
        }
        return findings;
    }

    /**
     * 从签名名提取被定义的算子：{@code __ + __} → {@code +}，{@code isEmpty} → {@code isEmpty}。
     * 返回 {@code null} 表示该签名是字面量（如 {@code 0,1}），不参与检查。
     */
    private static String operatorOf(String signatureName) {
        String trimmed = signatureName.trim();
        if (trimmed.isEmpty() || Character.isDigit(trimmed.charAt(0))) {
            return null;
        }
        String withoutPlaceholders = trimmed.replace("_", " ").trim();
        if (withoutPlaceholders.isEmpty()) {
            return null;                        // 形如 "__ __" 的纯占位
        }
        // 中缀形式只保留算子部分
        String[] parts = withoutPlaceholders.split("\\s+");
        return parts.length == 1 ? parts[0] : withoutPlaceholders.replace(" ", "");
    }

    private static Set<String> definedNames(Ast.Trait trait) {
        Set<String> defined = new LinkedHashSet<>();

        Ast.Asserts asserts = section(trait, Ast.Asserts.class);
        if (asserts != null) {
            for (Ast.Equation equation : asserts.equations()) {
                addRoot(equation.left(), defined);
            }
            asserts.generatedBy().forEach(ref -> defined.add(ref.name()));
            asserts.partitionedBy().forEach(ref -> defined.add(ref.name()));
        }

        Ast.Implies implies = section(trait, Ast.Implies.class);
        if (implies != null) {
            for (Ast.Equation equation : implies.equations()) {
                addRoot(equation.left(), defined);
            }
        }

        Ast.Converts converts = section(trait, Ast.Converts.class);
        if (converts != null) {
            converts.operators().forEach(ref -> defined.add(ref.name()));
        }
        return defined;
    }

    /** 等式左侧的根算子即为被定义的算子。 */
    private static void addRoot(Ast.Expr expr, Set<String> out) {
        if (expr instanceof Ast.Apply apply) {
            out.add(apply.function());
        } else if (expr instanceof Ast.Infix infix) {
            out.add(infix.operator());
        }
    }

    private static <T> T section(Ast.Trait trait, Class<T> type) {
        return trait.sections().stream()
                .filter(type::isInstance)
                .map(type::cast)
                .findFirst()
                .orElse(null);
    }
}
